### 6. Weak Random ID Generation

**Location:** DetachedProcessManager.ts:26

```typescript
const id = `detached-${Date.now()}-${Math.random().toString(36).substr(2, 9)}`
```

**Problems:**
- `Math.random()` is not cryptographically secure
- Potential collisions if multiple processes start at the same millisecond
- `substr` is deprecated (use `slice` or `substring`)

**Solution:**
```typescript
import * as crypto from "crypto"

// Use crypto.randomBytes for better randomness
const id = `detached-${Date.now()}-${crypto.randomBytes(6).toString("hex")}`
// Or use crypto.randomUUID() if you want a full UUID
```

---

### 7. No Log File Cleanup Strategy

**Location:** DetachedProcessManager.ts:27

```typescript
const logFilePath = path.join(os.tmpdir(), `cline-${id}.log`)
```

**Problems:**
- Log files accumulate in `/tmp` forever
- No size limits (a command could output gigabytes)
- No rotation mechanism
- No cleanup after N days

**Solutions to consider:**

**A. Add a cleanup method:**
```typescript
/**
 * Clean up log files older than 24 hours and remove completed processes
 */
cleanupOldProcesses(): void {
  const now = Date.now()
  const ONE_DAY = 24 * 60 * 60 * 1000

  for (const [id, process] of this.processes.entries()) {
    // Remove completed/errored processes older than 1 day
    if (process.status !== "running" && (now - process.startTime) > ONE_DAY) {
      // Delete log file
      try {
        fs.unlinkSync(process.logFilePath)
      } catch (err) {
        // File might already be deleted, ignore
      }
      this.removeProcess(id)
    }
  }
}
```

**B. Add size limits to log streams:**
```typescript
let bytesWritten = 0
const MAX_LOG_SIZE = 10 * 1024 * 1024 // 10MB

process.on("line", (line: string) => {
  const lineBytes = Buffer.byteLength(line + "\n", "utf8")

  if (bytesWritten + lineBytes > MAX_LOG_SIZE) {
    logStream.write("\n... [Log truncated - size limit reached] ...\n")
    logStream.end()
    return
  }

  bytesWritten += lineBytes
  detached.lineCount++
  logStream.write(line + "\n")
})
```

